// Shared helpers. build.py pastes this file into every Code node that has the
// include line at its top, so n8n needs no external modules.

// Same algorithm runs in the Apps Script seeder, so a vendor keeps one ID
// from the first email through the form and the assessment.
function vendorIdFor(email) {
  const s = String(email || '').trim().toLowerCase();
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return 'EBM-V-' + h.toString(36).toUpperCase().padStart(7, '0').slice(-7);
}

// Models sometimes wrap JSON in fences or add a sentence before it.
function parseJson(text) {
  if (!text || typeof text !== 'string') return null;
  const cleaned = text.replace(/```(?:json)?/gi, '');
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try { return JSON.parse(cleaned.slice(start, end + 1)); } catch (e) { return null; }
}

function llmText(response) {
  const choice = response && response.choices && response.choices[0];
  return (choice && choice.message && choice.message.content) || '';
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function clip(s, n) {
  s = String(s == null ? '' : s).replace(/\s+\n/g, '\n').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}

// Turns one n8n form submission into a vendor record, joins it to the email the
// vendor first sent, and prepares the inputs for the official checks.

const FIELDS = [
  {
    "key": "vendor_id",
    "title": "Reference ID"
  },
  {
    "key": "company_name",
    "title": "Company legal name"
  },
  {
    "key": "contact_name",
    "title": "Contact person"
  },
  {
    "key": "contact_email",
    "title": "Contact email"
  },
  {
    "key": "phone",
    "title": "Phone"
  },
  {
    "key": "category",
    "title": "Supply category"
  },
  {
    "key": "offering",
    "title": "What do you supply?"
  },
  {
    "key": "website",
    "title": "Company website"
  },
  {
    "key": "city",
    "title": "City"
  },
  {
    "key": "years_in_business",
    "title": "Years in business"
  },
  {
    "key": "ntn",
    "title": "NTN"
  },
  {
    "key": "strn",
    "title": "STRN"
  },
  {
    "key": "secp_no",
    "title": "SECP registration number (CUIN)"
  },
  {
    "key": "directors",
    "title": "Owners or directors (full names)"
  },
  {
    "key": "director_cnics",
    "title": "CNIC numbers of the owners or directors (optional)"
  },
  {
    "key": "certifications",
    "title": "Certifications held"
  },
  {
    "key": "cert_expiry",
    "title": "Certificate expiry dates"
  },
  {
    "key": "turnover",
    "title": "Annual turnover (PKR)"
  },
  {
    "key": "capacity",
    "title": "Monthly capacity"
  },
  {
    "key": "key_clients",
    "title": "Key clients"
  },
  {
    "key": "payment_terms",
    "title": "Payment terms offered"
  },
  {
    "key": "related_party",
    "title": "Is any owner or director related to an EBM employee?"
  },
  {
    "key": "related_party_details",
    "title": "If yes, give the name and relationship"
  },
  {
    "key": "litigation",
    "title": "Any litigation, debarment or regulatory action in the last 5 years?"
  },
  {
    "key": "litigation_details",
    "title": "If yes, give details"
  },
  {
    "key": "declaration",
    "title": "Declaration"
  }
];

const sub = $('Vendor Form').first().json;
const intake = $('Find Vendor').first().json || {};

// Newer form versions key answers by field name, older ones by label.
const answer = f => {
  const raw = sub[f.key] !== undefined ? sub[f.key] : sub[f.title];
  return Array.isArray(raw) ? raw.join(', ') : String(raw == null ? '' : raw).trim();
};

const v = {};
for (const f of FIELDS) v[f.key] = answer(f);

v.contact_email = v.contact_email.toLowerCase();
// A form opened without the personal link has no reference; fall back to the email address.
if (!/^EBM-/.test(v.vendor_id)) v.vendor_id = intake.vendor_id || vendorIdFor(v.contact_email);
v.form_submitted_at = sub.submittedAt || new Date().toISOString();
v.website = v.website.replace(/^https?:\/\//i, '').replace(/\/$/, '');
v.original_email = intake.email_body ? `Subject: ${intake.subject}\n\n${intake.email_body}` : '';

// Directors as a clean list of names, for the sanctions check and web searches.
v.director_list = v.directors
  .replace(/\(.*?\)/g, '')
  .split(/[,;\n]| and /)
  .map(s => s.trim())
  .filter(s => s.split(/\s+/).length >= 2);

// SECP stores names as "XYZ (PRIVATE) LIMITED"; vendors often write "XYZ (Pvt) Ltd".
v.secp_query = v.company_name.toUpperCase()
  .replace(/\(\s*PVT\.?\s*\)|\bPVT\.?(?=\s)/g, '(PRIVATE)')
  .replace(/\bLTD\b\.?/g, 'LIMITED')
  .replace(/\s+/g, ' ')
  .trim();

return [{ json: v }];

// Runs the two official checks that need no database: the SECP company register
// and the UN Security Council sanctions list. A check that could not run is
// "unknown", never a pass.

const v = $('Normalize Vendor').first().json;
const secpHtml = String($('SECP Search').first().json.data || '');
const unXml = String($('UN Sanctions List').first().json.data || '');

// SECP returns an HTML table: Sr, Company Name, Status, CRO, Registration No., Registration Date, Last filing.
function secpRows(html) {
  const rows = [];
  for (const tr of html.match(/<tr[\s\S]*?<\/tr>/gi) || []) {
    // SECP leaves some <td> tags unclosed, so split on cell starts instead of matching pairs.
    const cells = tr.split(/<td[^>]*>/i).slice(1)
      .map(td => td.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim());
    if (cells.length >= 6 && /^\d+$/.test(cells[0])) {
      rows.push({ name: cells[1], status: cells[2], cro: cells[3], reg_no: cells[4], registered_on: cells[5], last_filing: cells[6] || '' });
    }
  }
  return rows;
}

// Lower-case, drop punctuation and legal suffixes so "Packages Ltd." matches "PACKAGES LIMITED".
const norm = s => String(s || '').toLowerCase()
  .replace(/[^a-z0-9 ]/g, ' ')
  .replace(/\b(m s|pvt|private|ltd|limited|co|company|the|smc|llc|inc)\b/g, ' ')
  .replace(/\s+/g, ' ').trim();

// Every individual and entity name (and alias) on the UN list.
function unNames(xml) {
  const names = [];
  for (const block of xml.match(/<(INDIVIDUAL|ENTITY)>[\s\S]*?<\/\1>/g) || []) {
    const kind = block.startsWith('<INDIVIDUAL') ? 'individual' : 'entity';
    const ref = (block.match(/<REFERENCE_NUMBER>([^<]*)</) || [])[1] || '';
    const parts = ['FIRST_NAME', 'SECOND_NAME', 'THIRD_NAME', 'FOURTH_NAME']
      .map(t => (block.match(new RegExp(`<${t}>([^<]*)<`)) || [])[1]).filter(Boolean);
    if (parts.length) names.push({ kind, ref, name: parts.join(' ') });
    for (const a of block.match(/<ALIAS_NAME>([^<]*)</g) || []) names.push({ kind, ref, name: a.replace(/<\/?ALIAS_NAME>/g, '') });
  }
  return names;
}

const lines = [];

// SECP company register
const found = secpRows(secpHtml);
const regNo = String(v.secp_no || '').replace(/\D/g, '').replace(/^0+/, '');
const sameNo = r => regNo && r.reg_no.replace(/\D/g, '').replace(/^0+/, '') === regNo;
const match = found.find(sameNo) || found[0];
const secp = { query: v.secp_query, found: Boolean(match), match: match || null };
if (!secpHtml) {
  lines.push({ check: 'secp', result: 'unknown', text: 'Could not reach the SECP company register.' });
} else if (!match) {
  lines.push({ check: 'secp', result: 'warn', text: `No company named "${v.secp_query}" in the SECP register. It may be a sole trader or partnership, or the name differs.` });
} else if (regNo && !sameNo(match)) {
  lines.push({ check: 'secp', result: 'warn', text: `Registered with SECP, but under number ${match.reg_no}, not ${v.secp_no} as stated on the form.` });
} else {
  lines.push({ check: 'secp', result: 'pass', text: `Registered company since ${match.registered_on} (${match.status}, ${match.cro}).` });
}

// UN sanctions list: exact match on the normalised company name or any director's name
const listed = unXml ? unNames(unXml) : [];
const wanted = [v.company_name, ...v.director_list].map(n => ({ query: n, key: norm(n) })).filter(q => q.key.length >= 4);
const hits = [];
for (const q of wanted) {
  for (const e of listed) if (norm(e.name) === q.key) hits.push({ query: q.query, ...e });
}
if (!listed.length) {
  lines.push({ check: 'sanctions', result: 'unknown', text: 'Could not load the UN sanctions list.' });
} else if (hits.length) {
  lines.push({ check: 'sanctions', result: 'fail', text: `"${hits[0].query}" matches "${hits[0].name}" on the UN sanctions list (${hits[0].ref}). A person must check this.` });
} else {
  lines.push({ check: 'sanctions', result: 'pass', text: `Company and directors not on the UN sanctions list (${listed.length} names checked).` });
}

return [{ json: { secp, sanctions: { hits, names_checked: listed.length }, lines } }];

// Three web searches: who they are, anything adverse about the company or its
// directors, and what their own site claims.

const v = $('Normalize Vendor').first().json;
const name = `"${v.company_name}"`;
const people = v.director_list.slice(0, 2).map(s => `"${s}"`);

const queries = [
  ['profile', `${name} ${v.city} Pakistan`],
  ['adverse', `${[name, ...people].join(' OR ')} fraud OR lawsuit OR debarred OR adulteration OR penalty OR FIR`],
  ['claims', v.website ? `${v.website} ${v.company_name} certification clients` : `${name} ${v.offering.split(/[,.]/)[0]} supplier reviews`],
];
return queries.map(([purpose, query]) => ({ json: { vendor_id: v.vendor_id, purpose, query } }));

